#include <iostream>
#include <cstdio>
using namespace std;

int digitCount(long long n) {
    int count = 0;
    while (n != 0) {
        n /= 10;
        count++;
    }
    return count;
}

long long maxOnesNumber(long long n) {
    int digits = digitCount(n);
    long long total = 0, base = 1;
    for (int i = 0; i < digits; i++) {
        total += base;
        base *= 10;
    }
    if (total <= n) return total;
    return (total - 1) / 10;
}

long long processNumber(long long n) {
    if (n <= 6) return n;
    if (n <= 11) return 13 - n;
    long long base = maxOnesNumber(n);
    long long nextVal = base * 10 + 1;
    if (n % base == 0) {
        if (n <= (nextVal / 2 + base))
            return digitCount(base) * n / base;
        return digitCount(nextVal) + processNumber(nextVal - n);
    } else {
        long long m = (n / base) * base;
        long long res = processNumber(m) + processNumber(n - m);
        if (n > nextVal / 2)
            res = min(processNumber(m) + processNumber(n - m), digitCount(nextVal) + processNumber(nextVal - n));
        return res;
    }
}

int main() {
    long long n;
    cin >> n;
    cout << processNumber(n) << endl;
    return 0;
}
